    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "ClinicoPath",
                name = "nogoldstandard",
                version = c(1,0,8),
                options = options,
                results = nogoldstandardResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
